using ghidra.framework.plugintool.util;
using ghidra.pty;
using ghidra.pty;

public class RunBashInTerminalScript : TerminalGhidraScript {
	/* @Override */
	protected void runSession(Pty pty)
    {
		Map<string, string> env = new(System.getenv());
		env.put("TERM", "xterm-256color");
		PtySession session = pty.getChild().session(new string[] { "/usr/bin/bash" }, env);
		displayInTerminal(pty, () => {
			try {
				session.waitExited();
			}
			catch (InterruptedException e) {
				return;
			}
		});
	}
}
